eq "$rc" 3; eq "$(verdict)" "VERDICT: FOLLOW-UP"; grep -q "^| rollup | 7 | 60 | 7 | 60 | +0% | OK | 14% | OK | 1 |" $MD/decide.md && grep -q "^| $B | 3 | 60 | 3 | 60 | +0% | OK | 33% | TRIP | 1 |" $MD/decide.md || exit 1
$C up $P >/dev/null || exit 1; mkdir -p $S/status $S/schedule && python3 -c "import json,sys,time; json.dump(dict(target=7, changed=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), starts=[]), open(sys.argv[1], 'w'))" $S/schedule/target.json
printf '[runtime.options]\nload_low = 1000\nload_high = 1001\nschedule_ramp = 10\nschedule_interval = 3600\n' > {state_dir}/org-a31.toml; P="$P --org-profile {state_dir}/org-a31.toml"
hand builder build "#12"; sleep 1; hand builder build "#13"; sleep 1; hand builder build "#14"; hand reviewer review "#15"
b=$(dec builder); r=$(dec reviewer); echo "follow-up filed, no hold: builder $b; reviewer $r"; eq "$b" "admit:b#12 admit:b#13 admit:b#14"; eq "$r" "admit:r#15"

