hold 12; b=$(dec builder); r=$(dec reviewer); echo "gate open, unstarted feature #12 held: builder $b; reviewer $r"; eq "$b" "admit:b#13 admit:b#14 held:b#12"; eq "$r" "admit:r#15 held:b#12"
hold; b=$(dec builder); echo "owner waiver, hold removed: builder $b"; eq "$b" "admit:b#12 admit:b#13 admit:b#14"

