P="$P --org-profile {state_dir}/org-a31.toml"
card() { python3 -c "import json,sys; d,lab,who=sys.argv[1:4]; body='**Source:** $R#5\n**Trigger:** owner-feedback\n**Failure class:** too-slow\n**Proposed fix:** cut the review wait\n**Scope:** repo: - product-local\n**Lesson:** none yet\n**Findings entry:** none yet\n**Decision:** %s' % d; json.dump([dict(number=16, title='intake: too-slow on $R#5', body=body, labels=[dict(name=l) for l in lab.split(',') if l], assignees=[dict(login=w) for w in who.split(',') if w])], open(sys.argv[4], 'w'))" "$@" $G/issue-list.json; }
FLAVOR="[Ash/flavor] #16: standard (default standard)\n\n<!-- crew:v1 role=coordinator pass=flavor issue=16 flavor=standard default=standard -->\n\n— Ash (CTO)"
rig() { python3 {source}/scripts/item-flavor.py --project $CREW_PROJECT --issue 16 --labels "$1" <<< "[\"$FLAVOR\"$2]"; }
r0=$(rig "" ""); cfg0=$(python3 {source}/core/crew-config.py resolve $P | shasum)
card pending "" "" && $C poll --once $P >/dev/null || exit 1
card "accept (repo:)" "crew:ready" "sandbox-builder"; $C poll --once $P; $C route $P >/dev/null
r1=$(rig "crew:ready" ", \"[Ash/intake] #16 accepted (repo:) as a builder issue\\\\n\\\\n— Ash (CTO)\""); cfg1=$(python3 {source}/core/crew-config.py resolve $P | shasum)
n=$(grep -l '"issue-assigned"' $S/leads/builder-events/*.json 2>/dev/null | xargs grep -l '#16' | wc -l | tr -d ' '); echo "accepted card #16 -> builder-lead work events: $n; rigor before: $r0; after: $r1"
eq "$n" 1; eq "$r1" "$r0"; eq "$cfg1" "$cfg0"
